// merge combines two sorted slices into a single sorted slice.
// Both inputs are assumed to be sorted in non-decreasing order.
func merge(a, b []int) []int {
	result := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
